// accountTitle is what Cloudflare calls the account, or else hakobu's key
// for it.
func accountTitle(c ops.ClientAccount) string {
	if c.Title != "" {
		return c.Title
	}
	return c.Name
}

// keysUnsaved tells whether the owner has no copy of a server's key.
func keysUnsaved(servers []ops.Server) bool {
	for _, sv := range servers {
		if sv.KeyKnown && !sv.Key.Exported {
			return true
		}
	}
	return false
}

// hasOwnAccounts tells whether the user connected accounts of their own,
// besides the panel's.
func hasOwnAccounts(clients []ops.ClientAccount) bool {
	for _, c := range clients {
		if !c.Panel {
			return true
		}
	}
	return false
}

func clientProjects(c ops.ClientAccount) string {
	if len(c.Projects) == 0 {
		return "no projects"
	}
	return strings.Join(c.Projects, ", ")
}

