func watching(a ops.AccountAlertsInfo) string {
	switch {
	case a.Watching == 0:
		return "no app with an address for the watchdog yet"
	case a.Watching == 1 && a.History:
		return "the watchdog checks 1 app and keeps its uptime"
	case a.Watching == 1:
		return "the watchdog checks 1 app"
	case a.History:
		return fmt.Sprintf("the watchdog checks %d apps and keeps their uptime", a.Watching)
	}
	return fmt.Sprintf("the watchdog checks %d apps", a.Watching)
}

func usersIntro(openSignup bool) string {
	const each = "Each user sees only their own projects, servers and Cloudflare accounts"
	if openSignup {
		return "Who has signed in. Anyone with a GitHub account signs up here. " + each + ", and runs projects only on their own; you keep the panel's settings."
	}
	return "Who can sign in. " + each + ", and deploys on this server and their own; you keep the panel's settings. Someone joins with an invite link: it works once, within a week."
}

// usersAction is the Invite button, where joining takes an invite.
